using V=json::Value;using O=V::Object;using A=V::Array;
void need(bool b,const char* s){if(!b)throw std::runtime_error(s);}
const V& f(const V& v,const std::string& k){const auto* p=v.find(k);need(p,"COMPILED_CHORD_FIELD");return *p;}
std::int64_t n(const V& v){std::int64_t x{};need(v.integer(x),"COMPILED_CHORD_INTEGER");return x;}
bool known(const V& v){if(v.null())return false;if(v.isString())return declared_manual_text::visibleUtf8(v.string());if(v.isObject())for(const auto& x:v.object())if(!known(x.second))return false;if(v.isArray())for(const auto& x:v.array())if(!known(x))return false;return true;}
bool includes(const V& actual,const V& expected){if(expected.isObject()){if(!actual.isObject())return false;for(const auto& p:expected.object()){const auto* a=actual.find(p.first);if(!a||!includes(*a,p.second))return false;}return true;}if(expected.isArray()){if(!actual.isArray()||actual.array().size()!=expected.array().size())return false;for(std::size_t i=0;i<expected.array().size();++i)if(!includes(actual.array()[i],expected.array()[i]))return false;return true;}return actual==expected;}
const O& compiled(){static const O table=[] {O result;const auto& input=compiled_chord_session_data::programs();need(f(input,"version")==V("B1145-source-chord-session-r14")&&f(input,"source_clock").null(),"COMPILED_CHORD_VERSION");for(const auto& r:f(input,"rows").array())need(result.emplace(f(r,"source_key").string(),r).second,"COMPILED_CHORD_UNIQUE_KEY");need(result.size()==40,"COMPILED_CHORD_EXACT40");return result;}();return table;}
struct Row{V source,program,flags;};std::map<std::string,Row> rows;
V& policy(O& policies,const std::string& key){auto& base=policies[key];if(base.null())base=O{{"reduction_required",false},{"trigger_unresolved",false},{"reported_bpm_ceiling",nullptr}};auto& p=base.object()["compiled_chord_session"];if(p.null())p=O{{"known_slower_window_debt",false},{"pending_owned_recovery_release",false},{"failed_window_witness",nullptr},{"retained_choices",nullptr},{"full_barre_cells_since_rest",V::fromInteger(0)},{"barre_count_initialized",false}};return p;}
const V* retained(const O& policies,const std::string& key){const auto i=policies.find(key);return i==policies.end()?nullptr:i->second.find("compiled_chord_session");}
bool flag(const Row& row,const char* name){return f(row.flags,name)==V(true);}
bool bpm(const V& v){std::int64_t value{};return v.integer(value)&&value>=1&&value<=500;}
int beats(const V& payload){const auto& s=f(payload,"chosen_slower_window");if(s==V("whole"))return 4;if(s==V("half"))return 2;need(s==V("quarter"),"COMPILED_CHORD_CLOSED_WINDOW");return 1;}
const V& expectation(const Row& row){return f(row.program,"source_expected_ordered_attacks");}
bool loss(const Row& row,const V& payload){const auto* reports=payload.find("actual_ordered_attacks");if(!reports)return false;for(const auto& p:reports->object()){const auto& exp=f(expectation(row),p.first);for(const char* field:{"chord_recognizable_reported","correct_bass_reported","unused_strings_silent_reported"})if(f(p.second,field)==V(false))return true;for(const char* field:{"reported_actual_chord","reported_actual_contacts"})if(const auto* a=p.second.find(field))if(known(*a)&&*a!=f(exp,field))return true;}return false;}
bool chosenPartial(const Row& row,const V& payload){const auto& orders=f(payload,"chosen_partial_string_order");const auto& domains=f(f(row.program,"choice_domains"),"partial_string_orders");for(const auto& d:domains.object()){const auto& a=f(orders,d.first).array();std::set<std::int64_t> source,selected;for(const auto& s:d.second.array())source.insert(n(s));for(const auto& s:a)selected.insert(n(s));if(a.size()!=4||selected!=source)return false;}return true;}
bool actualPartial(const Row& row,const V& payload,const V& choice){
 if(f(payload,"reported_chosen_partial_fingering")!=f(choice,"chosen_partial_fingering"))return false;
 const auto& source=f(f(row.source,"implementation"),"events").array();const auto& fingers=f(choice,"chosen_partial_fingering");
 const bool arpeggio=flag(row,"arpeggio");
 if(arpeggio&&(f(payload,"reported_chosen_partial_string_order")!=f(choice,"chosen_partial_string_order")||f(payload,"reported_chosen_partial_strokes")!=f(choice,"chosen_partial_strokes")))return false;
 for(std::size_t i=0;i<source.size();++i){const auto& actual=f(f(payload,"actual_ordered_attacks"),"attack_"+std::to_string(i+1));const auto& members=f(source.at(i),"members").array();const auto& chosenFingers=f(fingers,"bar_"+std::to_string(i/4+1)).array();
  if(arpeggio){const auto& string=f(f(choice,"chosen_partial_string_order"),"bar_"+std::to_string(i/4+1)).array().at(i%4);if(f(actual,"reported_actual_selected_string")!=string||f(actual,"reported_actual_selected_stroke")!=f(choice,"chosen_partial_strokes").array().at(i))return false;V expected;for(std::size_t j=0;j<members.size();++j)if(f(members[j],"string")==string){expected=members[j];expected.object()["finger"]=chosenFingers.at(j);}if(expected.null()||f(actual,"reported_actual_selected_contact")!=V(A{expected}))return false;
  }else{const auto& contacts=f(actual,"reported_actual_contacts").array();if(contacts.size()!=members.size())return false;for(std::size_t j=0;j<members.size();++j)if(f(contacts[j],"finger")!=chosenFingers.at(j))return false;}
 }
 return true;
}
