bool supports(const V& original){const auto* key=original.find("package_key");return key&&key->isString()&&compiled().count(key->string());}
V construct(const std::string& key,const V& original,const V& context,const V& contextRef){const auto i=compiled().find(key);need(i!=compiled().end()&&f(original,"package_key")==V(key)&&!rows.count(key),"COMPILED_CHORD_CLOSED_FACTORY");const auto& source=f(original,"implementation");const auto& r=i->second;need(f(source,"events")==f(r,"source_events")&&f(source,"instructions")==f(r,"source_instructions")&&contextRef==f(r,"source_context_ref"),"COMPILED_CHORD_ORIGINAL_JOIN");need(context.isObject(),"COMPILED_CHORD_CONTEXT");auto program=f(r,"program");program.object()["source_facts"]=source;rows.emplace(key,Row{original,program,f(r,"flags")});return program;}
bool guard(const V& op,const V& payload,const O& saved,const O& policies){need(op.isObject()&&op.object().size()==3&&f(op,"kind")==V("b_compiled_chord_session_controls"),"COMPILED_CHORD_CLOSED_OPERATOR");const auto& key=f(op,"source_key").string();const auto i=rows.find(key);need(i!=rows.end(),"COMPILED_CHORD_OWNED_KEY");const auto& row=i->second;const auto stage=f(op,"stage").string();const auto& nodes=f(f(row.program,"graph"),"nodes");need(nodes.find(stage)&&stage!="finished","COMPILED_CHORD_CLOSED_STAGE");if(!known(payload)||!includes(payload,f(f(nodes,stage),"expected")))return false;const auto* ps=retained(policies,key);
 if(stage=="session_choices"){if(flag(row,"arpeggio")&&!chosenPartial(row,payload))return false;if(flag(row,"full_barre")){const auto count=n(f(payload,"prior_full_barre_cells_since_rest_reported"));const auto rest=f(payload,"prior_full_rest_taken_reported");if(count>=4&&rest!=V(true))return false;if(ps&&f(*ps,"barre_count_initialized")==V(true)&&count<n(f(*ps,"full_barre_cells_since_rest"))&&rest!=V(true))return false;}return true;}
 if(stage=="rest_after_full_cell")return ps&&f(payload,"reported_retained_full_cells_since_rest")==f(*ps,"full_barre_cells_since_rest")&&(n(f(*ps,"full_barre_cells_since_rest"))<4||f(payload,"full_rest_after_four_full_cells_reported")==V(true));
 const auto found=saved.find("session_choices");const V* choice=found==saved.end()?nullptr:&found->second;
 if(stage=="slower_source_recovery"){if(!ps||f(*ps,"known_slower_window_debt")!=V(true)||f(*ps,"failed_window_witness").null()||f(*ps,"retained_choices").null())return false;choice=&f(*ps,"retained_choices");const auto& witness=f(*ps,"failed_window_witness");const auto& failed=f(witness,"reported_matching_manual_bpm");const auto& recovery=f(payload,"reported_manual_recovery_bpm");if(!bpm(failed)||!bpm(recovery)||f(payload,"chosen_slower_window")!=f(payload,"reported_slower_window")||static_cast<std::int64_t>(beats(payload))*n(failed)<=n(recovery))return false;for(const auto& a:f(payload,"actual_ordered_attacks").object())if(f(a.second,"reported_actual_chosen_window_quarters")!=V::fromInteger(beats(payload)))return false;
 }else if(flag(row,"one_beat")&&stage=="whole_source_session"){if(!choice||f(payload,"reported_chosen_manual_bpm")!=f(*choice,"chosen_manual_bpm")||(ps&&f(*ps,"known_slower_window_debt")==V(true)))return false;}
 if(!choice||f(payload,"reported_chosen_muting_method")!=f(*choice,"chosen_muting_method"))return false;if(flag(row,"partial")&&(stage=="silent_source_preparation"||stage=="whole_source_session")&&f(payload,"reported_chosen_partial_fingering")!=f(*choice,"chosen_partial_fingering"))return false;
 if(stage=="whole_source_session"||stage=="slower_source_recovery"){if(!includes(f(payload,"actual_ordered_attacks"),expectation(row)))return false;if(flag(row,"partial")&&!actualPartial(row,payload,*choice))return false;}
 if(stage=="actual_source_audit"&&(!policyComplete(key,policies)))return false;return true;
}
bool bodilyStop(const std::string& key,const V& payload){if(!rows.count(key)||!payload.isObject())return false;for(const char* field:{"pain_or_persistent_tension","numbness_reported","forearm_fatigue_reported","pressure_increasing_reported","burning_or_tingling_reported","hand_cannot_relax_after_release_reported"})if(const auto* p=payload.find(field))if(*p==V(true))return true;return false;}
void policyBefore(const std::string& key,const std::string& stage,const V& payload,O& policies){const auto i=rows.find(key);if(i==rows.end()||!flag(i->second,"one_beat")||stage!="whole_source_session"||!loss(i->second,payload))return;auto& ps=policy(policies,key);ps.object()["known_slower_window_debt"]=true;ps.object()["pending_owned_recovery_release"]=false;if(!f(ps,"failed_window_witness").null())return;const auto& choice=f(ps,"retained_choices");const auto* reported=payload.find("reported_chosen_manual_bpm");if(choice.null()||!reported||!bpm(*reported)||*reported!=f(choice,"chosen_manual_bpm"))return;ps.object()["failed_window_witness"]=O{{"source_key",key},{"source_stage",stage},{"reported_matching_manual_bpm",*reported},{"source_minimum_metric_window_quarters",A{V::fromInteger(1),V::fromInteger(1)}}};}
void policyAfter(const std::string& key,const std::string& stage,const V& payload,O& policies){const auto i=rows.find(key);if(i==rows.end())return;auto& ps=policy(policies,key);if(stage=="session_choices"){ps.object()["retained_choices"]=payload;if(flag(i->second,"full_barre")){ps.object()["full_barre_cells_since_rest"]=f(payload,"prior_full_rest_taken_reported")==V(true)?V::fromInteger(0):f(payload,"prior_full_barre_cells_since_rest_reported");ps.object()["barre_count_initialized"]=true;}}if(stage=="whole_source_session"&&flag(i->second,"full_barre"))ps.object()["full_barre_cells_since_rest"]=V::fromInteger(n(f(ps,"full_barre_cells_since_rest"))+1);if(stage=="rest_after_full_cell"&&f(payload,"full_rest_after_four_full_cells_reported")==V(true))ps.object()["full_barre_cells_since_rest"]=V::fromInteger(0);if(stage=="slower_source_recovery")ps.object()["pending_owned_recovery_release"]=true;}
void policyReleased(O& policies){for(auto& entry:policies)if(const auto* found=entry.second.find("compiled_chord_session")){auto& ps=entry.second.object()["compiled_chord_session"];if(f(*found,"pending_owned_recovery_release")==V(true)){ps.object()["known_slower_window_debt"]=false;ps.object()["pending_owned_recovery_release"]=false;ps.object()["failed_window_witness"]=nullptr;}}}
bool policyComplete(const std::string& key,const O& policies){const auto* ps=retained(policies,key);return !ps||(f(*ps,"known_slower_window_debt")==V(false)&&n(f(*ps,"full_barre_cells_since_rest"))<4);}
std::string policyRetryEntry(const std::string& key,const O& policies){const auto* ps=retained(policies,key);return ps&&f(*ps,"known_slower_window_debt")==V(true)?"slower_source_recovery":"";}
V policyView(const std::string& key,const O& policies){const auto* ps=retained(policies,key);return ps?*ps:V(nullptr);}
std::size_t rowCount(){return rows.size();}
